# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe "Timekeeping local relay" do
  let(:local_relay_projection_url) { "https://www.example.com" }

  # Sends the relay's real HTTP POST into this app, so the internal controller
  # checks the bearer token. WebMock's Rack adapter puts a plain Hash in
  # rack.session, which the app's cookie session store cannot read; the
  # internal API keeps no session, so the request goes in without one.
  def route_local_relay_posts_into_app
    app = lambda do |env|
      env.delete("rack.session")
      env.delete("rack.session.options")
      Rails.application.call(env)
    end
    stub_request(:post, "#{local_relay_projection_url}/internal/v1/timekeeping/entry-snapshots").to_rack(app)
  end

  def run_local_relay
    with_timekeeping_service_token do
      with_timekeeping_env("TIMEKEEPING_PROJECTION_URL", local_relay_projection_url) do
        route_local_relay_posts_into_app
        Timekeeping::RelayJob.perform_now
      end
    end
  end

  # Preparing the monolith moves the entries id sequence above every id it
  # loaded, so a local entry never reuses a projected entry's id. A row created
  # straight in timesheet_entries skips that step, so the spec does it here.
  def advance_local_entry_ids_past_projection
    highest = TimesheetEntry.unscoped.maximum(:id).to_i
    connection = ActiveRecord::Base.connection
    connection.select_value(
      "SELECT setval(pg_get_serial_sequence('entries', 'id'), #{Integer(highest) + 1}, false)"
    )
  end

  def prepare_local_relay_owner
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
  end

  def local_relay_owner_actor(company)
    user = create(:user)
    create(:employment, company:, user:)
    user.add_role("owner", company)
    [user, Timekeeping::LocalOwner::Actor.user(user_id: user.id, role: "owner")]
  end

  def local_relay_create_entry(company:, actor:, project:, duration:, note:)
    created = Timekeeping::LocalOwner.call(
      operation: :create, company_id: company.id, generation: TimekeepingOwnership.current.generation.to_s, actor:,
      params: { "idempotency_key" => SecureRandom.uuid,
                "body" => { "project_id" => project.id, "work_date" => Date.current.iso8601, "duration" => duration,
                            "note" => note, "source" => "manual", "source_metadata" => {} } }
    )
    expect(created.status).to be_between(200, 201)
    Timekeeping::LocalEntry.where(company_id: company.id).order(:created_at).last
  end

  def local_relay_update_entry(company:, actor:, entry:, body:)
    updated = Timekeeping::LocalOwner.call(
      operation: :update, company_id: company.id, generation: TimekeepingOwnership.current.generation.to_s, actor:,
      params: { "idempotency_key" => SecureRandom.uuid, "entry_id" => entry.id, "body" => body }
    )
    expect(updated.status).to eq(200)
  end

  def local_relay_report_entries(company)
    report = Reports::TimeEntries::ReportService.new(ActionController::Parameters.new({}), company).process
    report[:reports].flat_map { |group| group[:entries].to_a }
  end

  # "Test with no Timekeeping process running: an entry edit after a rollback is written locally,
  # delivered by the monolith relay, and shown in the projection and time report."
  it "delivers a post-rollback edit made through LocalOwner into timesheet_entries, the entry list and the time report, and marks the outbox sent" do
    prepare_local_relay_owner
    company = create(:company)
    other_company = create(:company)
    user, actor = local_relay_owner_actor(company)
    project = create(:project, client: create(:client, company:))
    other_project = create(:project, client: create(:client, company: other_company))
    other_user = create(:user)
    create(:employment, company: other_company, user: other_user)
    other_row = create(:timesheet_entry, project: other_project, user: other_user, note: "other company untouched",
                                         work_date: Date.current)
    other_row.update_columns(company_id: other_company.id)
    other_before = other_row.reload.attributes
    advance_local_entry_ids_past_projection

    entry = local_relay_create_entry(company:, actor:, project:, duration: 60.0, note: "before relay")
    expect(Timekeeping::LocalEntry.where(company_id: company.id).sole).to eq(entry)
    local_relay_update_entry(company:, actor:, entry:, body: { "note" => "after relay", "duration" => 135.0 })

    with_timekeeping_service_token do
      with_timekeeping_env("TIMEKEEPING_PROJECTION_URL", local_relay_projection_url) do
        route_local_relay_posts_into_app

        # Only the relay writes timesheet_entries in the prepared state.
        expect(TimesheetEntry.unscoped.where(id: entry.id, note: "after relay")).not_to exist
        expect(local_relay_report_entries(company).map(&:id)).not_to include(entry.id)

        Timekeeping::RelayJob.perform_now
      end
    end

    projected = TimesheetEntry.unscoped.find(entry.id)
    expect(projected.attributes.slice("note", "duration", "company_id"))
      .to eq("note" => "after relay", "duration" => 135.0, "company_id" => company.id)
    expect(TimesheetEntry.unscoped.where(id: entry.id).count).to eq(1)

    listed = Timekeeping::EntryReader.list(company_id: company.id, user_id: user.id, from: Date.current, to: Date.current)
    expect(listed.find { |row| row.id == entry.id }.note).to eq("after relay")

    reported = local_relay_report_entries(company)
    expect(reported.filter_map { |row| row.note if row.id == entry.id }).to eq(["after relay"])
    expect(reported.map(&:id)).not_to include(other_row.id)

    outbox = Timekeeping::LocalOutboxEntry.where(company_id: company.id)
    expect(outbox.count).to be >= 1
    expect(outbox.where(sent_at: nil)).not_to exist
    expect(other_row.reload.attributes).to eq(other_before)
  end

  # "The token comes from the existing `TIMEKEEPING_SERVICE_TOKEN`. `Internal::V1::BaseController` accepts that token."
  # The receiver keeps the environment token; only the sender is given a different one.
  it "leaves the outbox unsent and timesheet_entries untouched when the sender's token does not match the receiver's" do
    prepare_local_relay_owner
    company = create(:company)
    _user, actor = local_relay_owner_actor(company)
    project = create(:project, client: create(:client, company:))
    entry = local_relay_create_entry(company:, actor:, project:, duration: 30.0, note: "refused delivery")
    expect(Timekeeping::LocalOutboxEntry.where(company_id: company.id, sent_at: nil)).to exist

    statuses = []
    with_timekeeping_service_token do
      route_local_relay_posts_into_app
      wrong = Timekeeping::LocalSnapshotEndpoint.new(
        endpoint: TimekeepingRelay::HttpEndpoint.new(url: local_relay_projection_url, token: "wrong-token"),
        logger: Logger.new(StringIO.new)
      )
      recording = Object.new
      recording.define_singleton_method(:deliver) do |batch, idempotency_key:|
        wrong.deliver(batch, idempotency_key:).tap { |answer| statuses << answer.status }
      end
      allow(Timekeeping::LocalSnapshotEndpoint).to receive(:configured).and_return(recording)

      Timekeeping::RelayJob.perform_now
    end

    expect(statuses).to eq([401])
    expect(TimesheetEntry.unscoped.where(id: entry.id)).not_to exist
    expect(Timekeeping::LocalOutboxEntry.where(company_id: company.id, sent_at: nil).count)
      .to eq(Timekeeping::LocalOutboxEntry.where(company_id: company.id).count)
  end

  it "stores a subnormal duration edit in timesheet_entries with the bits it was written with" do
    prepare_local_relay_owner
    company = create(:company)
    _user, actor = local_relay_owner_actor(company)
    project = create(:project, client: create(:client, company:))
    entry = local_relay_create_entry(company:, actor:, project:, duration: 60.0, note: "subnormal")
    local_relay_update_entry(company:, actor:, entry:, body: { "duration" => 5e-324 })

    run_local_relay

    projected = TimesheetEntry.unscoped.find(entry.id).duration
    expect([projected].pack("G")).to eq([5e-324].pack("G"))
    expect(Timekeeping::LocalOutboxEntry.where(company_id: company.id, sent_at: nil)).not_to exist
  end

  it "keeps one timesheet_entries row with the newest values when already delivered rows are sent again" do
    prepare_local_relay_owner
    company = create(:company)
    _user, actor = local_relay_owner_actor(company)
    project = create(:project, client: create(:client, company:))
    entry = local_relay_create_entry(company:, actor:, project:, duration: 60.0, note: "first")
    local_relay_update_entry(company:, actor:, entry:, body: { "note" => "newest", "duration" => 90.0 })

    run_local_relay
    Timekeeping::LocalOutboxEntry.where(company_id: company.id).update_all(sent_at: nil)
    run_local_relay

    rows = TimesheetEntry.unscoped.where(id: entry.id)
    expect(rows.count).to eq(1)
    expect(rows.sole.attributes.slice("note", "duration")).to eq("note" => "newest", "duration" => 90.0)
    expect(Timekeeping::LocalOutboxEntry.where(company_id: company.id, sent_at: nil)).not_to exist
  end
end
